var n=`1347-anticucho-boliviano`;var a=`world-1347`;var t=`BO`;var r=`south-america`;var s=4;var o=106;var g={en:`Anticucho Boliviano`,ua:`Болівійський антікучо`};var h={en:`Anticucho Boliviano is a dish from Bolivia featuring beef heart, aji panca paste, garlic, white vinegar. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Болівійський антікучо, страва кухні країни Болівія з такими основними складниками: яловиче серце, паста ахі панка, часник, білий оцет. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 70 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 70 хвилин.`,t:[`marinating`],m:70,i:[[`beef-heart`,820,`g`],[`aji-panca-paste`,65,`g`],[`garlic`,5,`clove`],[`ground-cumin`,5,`g`],[`white-vinegar`,110,`ml`]]},{en:`Thread the already marinated pieces on skewers, leaving small gaps for even cooking.`,ua:`Нанизайте раніше замариновані шматочки на шпажки з невеликими проміжками для рівного прогрівання.`,t:[`threading-skewers`],m:10,i:[]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:18,i:[]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`potato`,400,`g`],[`peanut`,90,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var l={slug:n,id:a,country:`BO`,region:r,servings:4,minutes:106,title:g,text:h,steps:d};export{t as country,l as default,a as id,o as minutes,r as region,s as servings,n as slug,d as steps,h as text,g as title};